#include<bits/stdc++.h>
#define int long long
using namespace std;
int a[111111];
signed main() {
	freopen("Fence.in","r",stdin);
	freopen("Fence.out","w",stdout);
	int n;
	cin>>n;
	for(int i=1;i<=n;i++){
		cin>>a[i];
	}	
	int ans=0;
	for(int i=1;i<=n;i++){
		for(int j=i+1;j<=n;j++){
			ans=max(ans,min(a[i],a[j])*(j-i));
		}
	}
	cout<<ans;
	return 0;
}
